import { Disc, DownloadCloud } from "lucide-react";
import {
  Architecture,
  DownloadConfig,
  getIsoFilename,
  getMediaDescription,
  Media,
  ReleaseBranch,
} from "@/lib/download";

type DownloadSelectorProps = {
  config: DownloadConfig;
  onConfigChange: (config: DownloadConfig) => void;
  onOpenDownload: () => void;
};

const selectClass =
  "w-full rounded-xl border border-slate-800 bg-slate-950 px-4 py-3 text-slate-200 focus:border-debian focus:outline-none dark:border-slate-800 dark:bg-slate-950 dark:text-slate-200 light:border-slate-300 light:bg-slate-50 light:text-slate-800";

export function DownloadSelector({
  config,
  onConfigChange,
  onOpenDownload,
}: DownloadSelectorProps) {
  function update<K extends keyof DownloadConfig>(
    key: K,
    value: DownloadConfig[K],
  ) {
    onConfigChange({ ...config, [key]: value });
  }

  return (
    <section
      id="download"
      className="border-y border-slate-800/50 bg-slate-900/40 py-16 dark:border-slate-800/50 dark:bg-slate-900/40 light:border-slate-200 light:bg-slate-100"
    >
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        <div className="mb-12 text-center">
          <h2 className="text-3xl font-bold text-slate-100 dark:text-slate-100 light:text-slate-900">
            Quick Download Selector
          </h2>
          <p className="mt-2 text-slate-400 dark:text-slate-400 light:text-slate-600">
            Find the exact Debian image tailored for your hardware and use case.
          </p>
        </div>

        <div className="mx-auto max-w-4xl rounded-2xl border border-slate-800 bg-slate-900 p-6 shadow-xl dark:border-slate-800 dark:bg-slate-900 light:border-slate-200 light:bg-white sm:p-8">
          <div className="mb-8 grid grid-cols-1 gap-6 md:grid-cols-3">
            <label className="block text-xs font-semibold uppercase tracking-wider text-slate-400 dark:text-slate-400 light:text-slate-600">
              <span className="mb-2 block">1. Release Branch</span>
              <select
                value={config.branch}
                onChange={(event) =>
                  update("branch", event.target.value as ReleaseBranch)
                }
                className={selectClass}
              >
                <option value="stable">Stable 13 (Trixie) - Recommended</option>
                <option value="testing">Testing (Forky) - Next Gen</option>
                <option value="unstable">Unstable (Sid) - Rolling</option>
              </select>
            </label>
            <label className="block text-xs font-semibold uppercase tracking-wider text-slate-400 dark:text-slate-400 light:text-slate-600">
              <span className="mb-2 block">2. Architecture</span>
              <select
                value={config.architecture}
                onChange={(event) =>
                  update("architecture", event.target.value as Architecture)
                }
                className={selectClass}
              >
                <option value="amd64">64-bit PC (amd64 / x86_64)</option>
                <option value="arm64">
                  ARM64 / AArch64 (Raspberry Pi, Apple M-series VM)
                </option>
                <option value="i386">32-bit PC (i386)</option>
                <option value="ppc64el">POWER Processors (ppc64el)</option>
                <option value="riscv64">RISC-V 64-bit (riscv64)</option>
              </select>
            </label>
            <label className="block text-xs font-semibold uppercase tracking-wider text-slate-400 dark:text-slate-400 light:text-slate-600">
              <span className="mb-2 block">3. Installer / Desktop</span>
              <select
                value={config.media}
                onChange={(event) => update("media", event.target.value as Media)}
                className={selectClass}
              >
                <option value="netinst">Standard Netinst (Minimal ISO)</option>
                <option value="gnome">Live ISO with GNOME Desktop</option>
                <option value="kde">Live ISO with KDE Plasma</option>
                <option value="xfce">Live ISO with XFCE Light</option>
              </select>
            </label>
          </div>

          <div className="flex flex-col items-center justify-between gap-4 rounded-xl border border-slate-800/80 bg-slate-950/70 p-5 dark:border-slate-800/80 dark:bg-slate-950/70 light:border-slate-200 light:bg-slate-50 sm:flex-row">
            <div className="flex items-center gap-3">
              <div className="rounded-xl bg-debian/10 p-3 text-debian">
                <Disc className="h-6 w-6" />
              </div>
              <div>
                <div className="text-base font-semibold text-slate-200 dark:text-slate-200 light:text-slate-900">
                  {getIsoFilename(config)}
                </div>
                <div className="text-xs text-slate-400 dark:text-slate-400 light:text-slate-600">
                  Size: {getMediaDescription(config.media)}
                </div>
              </div>
            </div>
            <button
              type="button"
              onClick={onOpenDownload}
              className="flex w-full items-center justify-center gap-2 rounded-xl bg-debian px-6 py-3 text-sm font-bold text-white transition-all hover:bg-debian-hover sm:w-auto"
            >
              <DownloadCloud className="h-4 w-4" />
              <span>Download ISO</span>
            </button>
          </div>
        </div>
      </div>
    </section>
  );
}
